head.script:
// =============================================================================
/**
 * 업무 화면 VALIDATE 관련 함수
 *
 * @author Inswave Systems
 * @class validate
 * @namespace $c.validate
 */
// =============================================================================
scwin.onpageload = function() {

};


/**
 * @method
 * @name validateDataCollect
 * @description DataCollection 유효성을 검증하는 공통함수 *
 * @param {Object} validateObj 검증할 component 컨테이너 또는 gridView Component (id 문자열 허용)
 * @param {Object} options 통합 옵션 객체
 *   {
 * 		validateType:"alert",
 * 		checkType:"single",
 * 		focus:true,
 * 		editMode:true,
 * 		includeUnbound:false,
 *      fields: {
 * 			"컴포넌트ID(GridView는 컬럼ID)": { required:true, maxLength:15, ... }
 * 		}
 * }
 *   - 동작: validateType(alert|mark|all), checkType(single|multi), focus, editMode,
 *     includeUnbound(DataCollection 미바인딩 컴포넌트 포함 여부 — 기본 false)
 *   - fields: 필드별 검증 규칙 (값은 객체 형태)
 *   - 미바인딩 컴포넌트(분리 입력 칸 등)는 기본 건너뛴다(규칙 선언 시 console.info 로 알림).
 *     includeUnbound:true 지정 시 컴포넌트 ID 규칙으로 검증 — 표시명은 name 지정 권장(미지정 시 컴포넌트 ID)
 * @memberOf validate
 * @author WebSquare
 * @return {Boolean} 유효성 검증 결과 (모두 통과 시 true, 실패 시 false)
 * @hidden N
 * @exception
 * @example
    // 전체 옵션 예시 — 동작 옵션 4종 + 규칙 종류별 지정 예
    const options = {
        validateType : "alert",  // alert(알림) | mark(req 클래스 마킹) | all(알림+마킹). 기본 alert
        checkType    : "single", // single(첫 실패 즉시 중단·개별 알림) | multi(전건 수집 후 취합 알림). 기본 single
        focus        : true,     // 실패 항목 포커스 이동 여부. 기본 true
        editMode     : true,     // (그리드) 실패 셀 포커스 시 편집모드 진입 여부. 기본 true
        fields : {
            // 기본 규칙 — 필수/문자/길이
            ipbName    : { required : true, maxLength : 10, name : "사원명" },
            ipbAge     : { required : true, num : "n", fromNum : 1, toNum : 150, name : "나이" },
            ipbCode    : { allowChar : "0-9A-Z", ignoreChar : "#", fixLength : 8, name : "코드" },
            ipbRemark  : { minLength : 5, maxLength : 100, name : "비고" },

            // byte·자릿수 규칙 — 한/영 혼합 byte 제한, 정수.소수 자리수
            ipbCorpNm  : { required : true, maxLengthB : 80, name : "발행기관명" },      // 한글 40자/영문 80자
            ipbRate    : { num : "f", maxLengthF : "10.2", name : "수수료율" },          // 정수 10자리.소수 2자리

            // format 규칙 — email/phone/mobilePhone/date/birth/securityNumber/bizNum/corpNum/urlNoProtocol
            ipbEmail   : { required : true, format : "email", name : "이메일" },
            ipbBizNo   : { format : "bizNum", name : "사업자등록번호" },                 // 10자리+검증번호
            ipbCorpNo  : { format : "corpNum", name : "법인등록번호" },                  // 13자리+검증번호
            ipbHomeUrl : { format : "urlNoProtocol", name : "홈페이지" },                // http:// 등 포함 금지

            // 조건부 규칙 — 참조 컴포넌트 값으로 판정 (equals|notEquals|in|notEmpty, message 재정의 가능)
            ipbZipCd   : { emptyIf : { compID : "sbx_nation", notEquals : "410",
                                       message : "외국국적은 우편번호를 입력할 수 없습니다." }, name : "우편번호" },
            calChgDt1  : { requiredIf : { compID : "ipb_chgNm2", notEmpty : true,
                                          message : "상호변경내역1 변경일을 먼저 입력해주세요." }, name : "변경일1" },

            // 그룹 중복·체크박스 규칙
            sbxMonth1  : { duplicateGroup : "settleMonth", name : "결산월1" },           // 같은 그룹명 간 중복 금지
            sbxMonth2  : { duplicateGroup : "settleMonth", name : "결산월2" },
            chkAgree   : { checked : true, name : "개인정보 처리방침 동의" },            // 미체크("0"·false 포함) 실패

            // 명세 v3 신규 — 필드 focus/message 옵션·비교·특정 값 확인·byte 한/영 문구
            ipbCorpNo2 : { required : true, format : "corpNum", focus : "ipt_corpRegNo1",
                           name : "법인등록번호" },                                       // 실패 시 분리 입력 첫 칸으로 포커스 (§1)
            ipbNewYn   : { matchValue : { value : "Y", message : "아이디 중복확인 여부를 확인하십시오." },
                           focus : "ipt_integUsrId", name : "중복확인" },                 // 특정 값 확인 — 미입력도 실패 (§5)
            sbxMonthA  : { compare : { compareTarget : "sbxMonthB", compareType : "NOT_EQUAL",
                                       message : "동일한 결산월이 존재합니다.\n결산월을 확인해주세요!" },
                           focus : "sbxMonthB", name : "결산월" },                        // 두 컴포넌트 값 비교 (§4)
            ipbCorpNm2 : { maxLengthB : { value : 80, msgType : "korEng" }, name : "발행기관명" },  // "한글 26자 영문 80자" 문구 (§2)
            ipbUserId  : { required : true, minLength : 6, maxLength : 20,
                           composition : { value : "engNum", message : "아이디는 영문+숫자의 조합이어야 합니다." },
                           name : "아이디" }                                                       // 문자 클래스 조합 필수
        }
    };

    // 폼 컨테이너 검증 (async — await 호출)
    const isValid = await $c.validate.validateDataCollect(grp_form, options);
    if (!isValid) return;

    // 그리드 검증 — fields 키는 컬럼ID, duplicate 로 행 간 중복 금지
    const isGridValid = await $c.validate.validateDataCollect(grd_list, {
        validateType : "all", checkType : "multi",
        fields : {
            SETTLE_MONTH : { required : true, duplicate : true, name : "결산월" },
            EMAIL        : { format : "email", name : "이메일" }
        }
    });

    입력 허용 문자, 입력 허용 불가 문자, 최대 입력 문자수 설정은 GridView의 Column의 속성에서 설정한다. <br/>
    - required:true - 필수 입력 항목 여부 <br/>
    - allowChar:0-9 - 숫자만 입력(정수형) <br/>
    - allowChar:0-9. - 숫자만 입력(실수형) <br/>
    - ignoreChar:a-zA-Z - 입력 허용 불가 문자 <br/>
    - minLength:10 - 최소 입력 문자수 <br/>
    - maxLength:15 - 최대 입력 문자수 <br/>
    - fixLength:13 - 고정 입력 문자수 <br/>
    - minLengthB:20 - 최소 입력 byte 수 <br/>
    - maxLengthB:50 - 최대 입력 byte 수 <br/>
    - maxLengthF:10.2 - 최대 입력 정수 + 소수점 자리수(,제외)<br/>
    - num:n - 숫자(0-9만) <br/>
    - num:i - 정수(음수 부호 허용) <br/>
    - num:f - 실수(부호·소수점 허용) <br/>
    - fromNum:5 - 최소 입력 숫자 <br/>
    - toNum:10 - 최대 입력 숫자 <br/>
    - format:email - email format <br/>
    - format:date - date format <br/>
    - format:phone - phone format <br/>
    - format:mobilePhone - mobilePhone format <br/>
    - format:bizNum - 사업자번호 format (10자리+검증번호) <br/>
    - format:corpNum - 법인등록번호 format (13자리+검증번호) <br/>
    - format:urlNoProtocol - URL에 프로토콜(http:// 등) 포함 금지 <br/>
    - format:birth - 생년월일(주민번호 앞자리) format <br/>
    - checked:true - 체크박스 필수 체크(약관 동의 등 — 빈 값·"0"·false·"N" 모두 실패) <br/>
    - emptyIf:{compID, equals|notEquals|in|notEmpty, message} - 참조 컴포넌트 조건 충족 시 입력 금지 <br/>
      (예: 국가코드가 대한민국(410)이 아니면 외국국적으로 판단해 입력 금지 —
      emptyIf : { compID : "sbx_nation", notEquals : "410", message : "외국국적은 우편번호를 입력할 수 없습니다." }) <br/>
    - requiredIf:{compID, equals|notEquals|in|notEmpty, message} - 참조 컴포넌트 조건 충족 시 필수 입력 <br/>
      (예: requiredIf : { compID : "ipb_chgNm2", notEmpty : true, message : "상호변경내역1 변경일을 먼저 입력해주세요." }) <br/>
    - duplicate:true - (그리드) 컬럼 값 행 간 중복 금지 <br/>
    - duplicateGroup:"그룹명" - (폼) 같은 그룹명을 지정한 필드 간 값 중복 금지 (예: 결산월1~n) <br/>
    - focus:"컴포넌트ID" - 검증 실패 시 포커스 이동 대상 지정(분리 입력 등 — 미지정 시 실패 컴포넌트 자신) <br/>
    - message:"문구" - required 실패 기본 문구 재정의 <br/>
    - matchValue:{value|values,message} - 특정 값 일치 확인(미입력도 실패 — 중복확인 여부 등 상태 플래그 점검) <br/>
    - compare:{compareTarget,compareType:"EQUAL"|"NOT_EQUAL",message} - 두 컴포넌트 값 비교(둘 다 입력 시 판정) <br/>
    - maxLengthB:{value,msgType:"korEng"} - byte 한도 + "한글 N자 영문 M자" 안내 문구(한글 3byte 환산) <br/>
    - composition:"engNum"|"engNumSpecial"|["eng","num",...] - 문자 클래스 조합 필수(각 1자 이상 포함 —
      eng/num/kor/special/upper/lower, 객체형 {value,message} 로 문구 재정의. allowChar 는 문자 제한, composition 은 포함 강제) <br/>

    ※ byte 길이(minLengthB/maxLengthB)는 UTF-8 기준(한글 3byte)으로 계산한다. <br/>
    ※ required 기본 문구는 컴포넌트 유형에 따라 자동 분기된다 — 선택형(radio/checkbox/selectbox 등)
    "…선택하세요.", 입력형 "…입력하세요.". <br/>
    ※ ignoreChar·byte 길이·num·범위·format 추가분·composition·emptyIf·duplicate·compare 계열 규칙은
    빈 값을 통과시킨다(필수 항목은 required 또는 requiredIf 병행 지정). checked·matchValue 는 빈 값도 실패.
 */
scwin.validateDataCollect = async function (validateObj, options) {
    options = Object.assign({ validateType : "alert", checkType : "single", focus : true, editMode : true, includeUnbound : false, fields : {} }, options);
    const fields = options.fields || {};

    if ($c.util.isEmpty(validateObj) || $c.util.isEmpty(fields)) return false;

    validateObj = (typeof validateObj === "string") ? $p.getComponentById(validateObj) : validateObj;
    if ($c.util.isEmpty(validateObj)) return false;

    const validateType = options.validateType.toUpperCase();
    const checkType = options.checkType.toUpperCase();
    const isGrid = (validateObj.getPluginName().toUpperCase() === "GRIDVIEW");

    // 컴포넌트 ID 추출 (getID 우선, 없으면 .id)
    const getCompId = function (comp) {
        return (typeof comp.getOriginalID === "function") ? comp.getOriginalID() : comp.id;
    };

    let validateResult = true;
    let messageArr = [];
    let firstObj = null;

    if (!isGrid) {
        let objArr = [];

        try {
            // 컴포넌트 수집도 try 내부에서 수행 — 실패 시 catch 로 false 반환
            objArr = $c.validate.getChildrenComponent(validateObj, {
                includePlugin: "autoComplete checkbox checkcombobox input inputCalendar radio selectbox searchbox secret textarea",
                recursive: true,
            });

            // req class 초기화 - 현재 미리 req class를 적용한 상태로 사용하기 때문에 초기화 코드는 사용하지 않음
            objArr.forEach(obj => {
                if (typeof obj.removeClass !== "undefined") {
                    //obj.removeClass("req");
                }
            });

			let isBreak = false;

            // options.fields(컴포넌트ID 또는 컬럼ID 기준) 규칙으로 validation 진행
            objArr.some(valObj => {
				if (isBreak) return true;

                let dataObjInfo = $c.validate.getDataCollection(valObj);
                if ($c.util.isEmpty(dataObjInfo)) {
                    // DataCollection 미바인딩 컴포넌트(분리 입력 칸 등) — 기본은 건너뛴다(하위호환).
                    // includeUnbound : true 지정 시 컴포넌트 ID 규칙으로 검증하며, 표시명은 name 미지정 시 컴포넌트 ID.
                    if (!options.includeUnbound) {
                        if (!$c.util.isEmpty(fields[getCompId(valObj)])) {
                            // 규칙이 선언돼 있는데 조용히 무시되는 사례 가시화
                            console.info("[validateDataCollect] DataCollection 미바인딩으로 규칙을 건너뜀: "
                                + getCompId(valObj) + " (options.includeUnbound : true 로 포함 가능)");
                        }
                        return;
                    }
                    dataObjInfo = { columnId : undefined, columnName : getCompId(valObj) };
                }

                const rules = fields[getCompId(valObj)] || fields[dataObjInfo.columnId];
                if ($c.util.isEmpty(rules)) return;

                const valInfo = Object.assign({ id : getCompId(valObj), name : undefined }, rules);

                for (const key of Object.keys(valInfo)) {
                    // id/name/focus/message 는 규칙이 아닌 메타 옵션 — 규칙 평가에서 제외 (focus·message: 명세 §1·§5)
                    if (key === "id" || key === "name" || key === "focus" || key === "message") continue;
                    const validateKey = key.toUpperCase();
                    const val = String(valInfo[key]);
                    if (!val) continue;

                    const result = $c.validate.validateDataGroup(validateKey, val, valInfo, valObj, dataObjInfo, checkType, validateType, options);
                    validateResult = (validateResult) ? result.validateResult : false;
                    messageArr.push(...result.messageArr);
                    (firstObj === null) && (firstObj = result.firstObj);

                    if (checkType === "SINGLE" && !validateResult) {
						isBreak = true;
						break;
					}
                }
            });

            // 전체 validate 메시지 출력
            if (!validateResult && (validateType === "ALERT" || validateType === "ALL") && checkType === "MULTI") {
                const message = messageArr.map(msg => `<p class="txt_hyphen">${msg}</p>`).join("");
                const height = 223 + ((messageArr.length > 4) ? (messageArr.length - 3) * 21 : 0);
                $c.win.alert(message, function() {
                    if (options.focus) firstObj?.focus();
                }, { disableCloseButton : false, height : height, width : 400 });
            } else if (!validateResult) {
                //if (options.focus) firstObj?.focus();
            }

        } catch (ex) {
            // finally 의 return 이 catch 의 return 을 덮어쓰지 않도록 finally 에서는 반환하지 않는다 (예외 시 항상 false)
            console.error(ex);
            return false;
        } finally {
            objArr = null;
        }
        return validateResult;
    } else {
        try {
            const gridViewCollect = await $c.validate.getGridViewDataList(validateObj);
            const gridViewData = gridViewCollect.getAllJSON();

			let isBreak = false;

            // GridView row × column, options.fields(컬럼ID 기준) 규칙으로 validation 진행
            gridViewData.some((rowData, rowIndex) => {
				if (isBreak) return true;

                Object.keys(rowData).some((columnId, colIndex) => {
					if (isBreak) return true;

                    const rules = fields[columnId];
                    if ($c.util.isEmpty(rules)) return;

                    const valInfo = Object.assign({ id : columnId, name : undefined }, rules);

                    for (const key of Object.keys(valInfo)) {
                        // id/name/focus/message 는 규칙이 아닌 메타 옵션 — 규칙 평가에서 제외 (focus·message: 명세 §1·§5)
                        if (key === "id" || key === "name" || key === "focus" || key === "message") continue;
                        const validateKey = key.toUpperCase();
                        const val = String(valInfo[key]);
                        if (!val) continue;

                        const result = $c.validate.validateDataCollection(validateKey, val, valInfo, validateObj, gridViewCollect, rowIndex, colIndex, checkType, validateType, options);
                        validateResult = (validateResult) ? result.validateResult : false;
                        messageArr.push(...result.messageArr);
                        (firstObj === null) && (firstObj = result.firstObj);

                        if (checkType === "SINGLE" && !validateResult) {
							isBreak = true;
							break;
						}
                    }
                });
            });

            // 전체 validate 메시지 출력
            if (!validateResult && (validateType === "ALERT" || validateType === "ALL") && checkType === "MULTI") {
                const message = messageArr.map(msg => `<p class="txt_hyphen">${msg}</p>`).join("");
                const height = 223 + ((messageArr.length > 4) ? (messageArr.length - 3) * 21 : 0);
                $c.win.alert(message, function() {
                    if (options.focus) firstObj?.focus();
                }, { disableCloseButton : false, height : height, width : 400 });
            } else if (!validateResult) {
                if (options.focus) firstObj?.focus();
            }

        } catch (ex) {
            // finally 의 return 이 catch 의 return 을 덮어쓰지 않도록 별도 finally 없이 반환한다 (예외 시 항상 false)
            console.error(ex);
            return false;
        }
        return validateResult;
    }
};

/**
 * @method
 * @name validateDataGroup
 * @description 데이터 유효성 확인
 * @param {string} validateKey validate key 값
 * @param {string} val validate key value 값
 * @param {string} valInfo validate 정보 값
 * @param {string} valObj component 객체
 * @param {string} dataObjInfo dataCollection 객체
 * @param {string} checkType validate check 방식 (SINGLE, MULTI)
 * @param {string} validateType validate 처리 방식 (ALERT, MARK, ALL)
 * @param {object} options validate 옵션
 * @returns {object} 데이터 유효성 검증 결과 ({ validateResult, messageArr, firstObj })
 * @hidden N
 * @exception
 * @example
 */
scwin.validateDataGroup = function (validateKey, val, valInfo, valObj, dataObjInfo, checkType, validateType, options) {
    let validateResult = true;
    const messageArr = [];
    let firstObj = null;
    const valObjValue = valObj.getValue();
    const name = $c.str.attachPostposition(valInfo.name || dataObjInfo.columnName);
    const focusObj = $c.validate.resolveFocusObj(valInfo, valObj);   // 명세 §1 — 필드 focus 지정 시 해당 컴포넌트로 이동

    // 실패 공통 처리 — 알림(SINGLE 즉시/MULTI 취합)·마킹·포커스 (모든 규칙 공용)
    const fail = function (msg, alertOpts) {
        if (validateType === "ALERT" || validateType === "ALL") {
            (firstObj === null) && (firstObj = focusObj);

            if (checkType === "SINGLE") {
                $c.win.alert(msg, function () {
                    if (options.focus) scwin.setFocus(focusObj);
                }, Object.assign({ disableCloseButton : false }, alertOpts));
            } else {
                messageArr.push(msg);
            }
        }

        if (validateType === "MARK" || validateType === "ALL") {
            (firstObj === null) && (firstObj = focusObj);
            valObj.addClass("req");
            if (options.focus) scwin.setFocus(focusObj);
        }

        validateResult = false;
    };

    if (validateKey === "REQUIRED" && val.toUpperCase() === "TRUE") {
        if (valObjValue === "") {
            // 컴포넌트 유형별 문구 분기(선택/입력 — 명세 §3) + 필드 message 재정의(명세 §5)
            fail($c.validate.getRequiredMessage(name, valInfo, valObj));
        }
    }

    if (validateKey === "ALLOWCHAR") {
        if (valObjValue.length !== ((valObjValue.match(new RegExp("[" + val + "]", "g")) === null) ? 0 : valObjValue.match(new RegExp("[" + val + "]", "g")).length)) {
            // 조합 인식 시 세부 문구(명세 §7), 인식 불가 조합은 기존 범용 문구
            fail(scwin.__getAllowCharMessage(name, val) || `${name} 허용된 문자(${val})만 입력해주세요.`);
        }
    }

    if (validateKey === "FORMAT") {
        if (val.toUpperCase() === "BIRTH" && !scwin.isBirthDay(valObjValue)) {
            fail(`${name} 정확한 생년월일을 입력해주세요.`);
        } else if (val.toUpperCase() === "DATE" && !scwin.isValidDate(valObjValue)) {
            fail(`${name} 정확한 날짜 형식을 입력해주세요.`);
        } else if (val.toUpperCase() === "MOBILEPHONE" && !$c.str.isMobilePhone(valObjValue)) {
            fail(`${name} 정확한 모바일폰 형식을 입력해주세요.`, { width : 400 });
        } else if (val.toUpperCase() === "PHONE" && !$c.str.isPhone(valObjValue)) {
            fail(`${name} 정확한 전화번호 형식을 입력해주세요.`, { width : 400 });
        } else if (val.toUpperCase() === "SECURITYNUMBER" && !$c.str.isSSN(valObjValue)) {
            fail(`${name} 정확한 주민등록번호 형식을 입력해주세요.`);
        } else if (val.toUpperCase() === "EMAIL" && !$c.str.isEmail(valObjValue)) {
            fail(`${name} 정확한 이메일 형식을 입력해주세요.`);
        }
    }

    if (validateKey === "FIXLENGTH") {
        if (valObjValue.length !== Number.parseInt(val)) {
            fail(`${name} 고정길이(${val})로 입력해주세요.`);
        }
    }

    if (validateKey === "MINLENGTH") {
        if (valObjValue.length < Number.parseInt(val)) {
            fail(`${name} 최소길이(${val}) 보다 크게 입력해주세요.`);
        }
    }

    if (validateKey === "MAXLENGTH") {
        if (valObjValue.length > Number.parseInt(val)) {
            fail(`${name} 최대길이(${val}) 보다 작게 입력해주세요.`);
        }
    }

    // 확장 규칙(ignoreChar/byte 길이/num/범위/format 추가분) + 조건부·그룹 규칙(checked/emptyIf/requiredIf/duplicateGroup/compare/matchValue)
    let extMsg = $c.validate.getExtendedRuleMessage(validateKey, val, valObjValue, valInfo.name || dataObjInfo.columnName, valInfo);
    if (extMsg === null) {
        extMsg = $c.validate.getConditionalRuleMessage(validateKey, valInfo, valObjValue, valInfo.name || dataObjInfo.columnName, options, dataObjInfo);
    }
    if (extMsg !== null) {
        fail(extMsg);
    }

    return { validateResult, messageArr, firstObj };
};

/**
 * @method
 * @name validateDataCollection
 * @description DataCollection 데이터 유효성 확인
 * @param {string} validateKey validate key 값
 * @param {string} val validate key value 값
 * @param {string} valInfo validate 정보 값
 * @param {object} valObj gridView component 객체
 * @param {object} dataObjInfo dataCollection 객체
 * @param {number} rowIndex row index
 * @param {number} colIndex column index
 * @param {string} checkType validate check 방식 (SINGLE, MULTI)
 * @param {string} validateType validate 처리 방식 (ALERT, MARK, ALL)
 * @param {object} options validate 옵션
 * @returns {object} 데이터 유효성 검증 결과 ({ validateResult, messageArr, firstObj })
 * @hidden N
 * @exception
 * @example
 */
scwin.validateDataCollection = function (validateKey, val, valInfo, valObj, dataObjInfo, rowIndex, colIndex, checkType, validateType, options) {
    let validateResult = true;
    const messageArr = [];
    let firstObj = null;
    const valObjValue = valObj.getCellData(rowIndex, colIndex);
    const name = $c.str.attachPostposition(valInfo.name || dataObjInfo.getColumnName(colIndex));
    const focusObj = $c.validate.resolveFocusObj(valInfo, valObj);   // 명세 §1 — 필드 focus 지정 시 해당 컴포넌트로 이동

    // 포커스 공통 처리 — focus 지정 컴포넌트가 있으면 그 컴포넌트로, 없으면 실패 셀로(편집모드 포함)
    const doFocus = function () {
        if (!options.focus) { return; }
        if (focusObj !== valObj) {
            scwin.setFocus(focusObj);
        } else {
            scwin.setFocus(valObj, rowIndex, colIndex, options.editMode);
        }
    };

    // 실패 공통 처리 — 알림(SINGLE 즉시/MULTI 취합)·셀 마킹·포커스 (모든 규칙 공용)
    const fail = function (msg, alertOpts) {
        if (validateType === "ALERT" || validateType === "ALL") {
            (firstObj === null) && (firstObj = (focusObj !== valObj) ? focusObj : valObj);

            if (checkType === "SINGLE") {
                $c.win.alert(msg, function () {
                    doFocus();
                }, Object.assign({ disableCloseButton : false }, alertOpts));
            } else {
                messageArr.push(msg);
            }
        }

        if (validateType === "MARK" || validateType === "ALL") {
            (firstObj === null) && (firstObj = (focusObj !== valObj) ? focusObj : valObj);
            valObj.setCellClass(rowIndex, colIndex, "req");
            doFocus();
        }

        validateResult = false;
    };

    if (validateKey === "REQUIRED" && val.toUpperCase() === "TRUE") {
        if (valObjValue === "") {
            // 컬럼 inputType 별 문구 분기(선택/입력 — 명세 §3) + 필드 message 재정의(명세 §5)
            fail($c.validate.getRequiredMessage(name, valInfo, valObj, colIndex));
        }
    }

    if (validateKey === "ALLOWCHAR") {
        if (valObjValue.length !== ((valObjValue.match(new RegExp("[" + val + "]", "g")) === null) ? 0 : valObjValue.match(new RegExp("[" + val + "]", "g")).length)) {
            // 조합 인식 시 세부 문구(명세 §7), 인식 불가 조합은 기존 범용 문구
            fail(scwin.__getAllowCharMessage(name, val) || `${name} 허용된 문자(${val})만 입력해주세요.`);
        }
    }

    if (validateKey === "FORMAT") {
        if (val.toUpperCase() === "BIRTH" && !scwin.isBirthDay(valObjValue)) {
            fail(`${name} 정확한 생년월일을 입력해주세요.`);
        } else if (val.toUpperCase() === "DATE" && !scwin.isValidDate(valObjValue)) {
            fail(`${name} 정확한 날짜 형식을 입력해주세요.`);
        } else if (val.toUpperCase() === "MOBILEPHONE" && !$c.str.isMobilePhone(valObjValue)) {
            fail(`${name} 정확한 모바일폰 형식을 입력해주세요.`, { width : 400 });
        } else if (val.toUpperCase() === "SECURITYNUMBER" && !$c.str.isSSN(valObjValue)) {
            fail(`${name} 정확한 형식을 입력해주세요.`);
        } else if (val.toUpperCase() === "PHONE" && !$c.str.isPhone(valObjValue)) {
            fail(`${name} 정확한 전화번호 형식을 입력해주세요.`, { width : 400 });
        } else if (val.toUpperCase() === "EMAIL" && !$c.str.isEmail(valObjValue)) {
            fail(`${name} 정확한 이메일 형식을 입력해주세요.`);
        }
    }

    if (validateKey === "FIXLENGTH") {
        if (valObjValue.length !== Number.parseInt(val)) {
            fail(`${name} 고정길이(${val})로 입력해주세요.`);
        }
    }

    if (validateKey === "MINLENGTH") {
        if (valObjValue.length < Number.parseInt(val)) {
            fail(`${name} 최소길이(${val}) 보다 크게 입력해주세요.`);
        }
    }

    if (validateKey === "MAXLENGTH") {
        if (valObjValue.length > Number.parseInt(val)) {
            fail(`${name} 최대길이(${val}) 보다 작게 입력해주세요.`);
        }
    }

    // 확장 규칙(ignoreChar/byte 길이/num/범위/format 추가분) + 조건부·그룹 규칙(checked/emptyIf/requiredIf/duplicate/compare/matchValue)
    let extMsg = $c.validate.getExtendedRuleMessage(validateKey, val, valObjValue, valInfo.name || dataObjInfo.getColumnName(colIndex), valInfo);
    if (extMsg === null) {
        extMsg = $c.validate.getConditionalRuleMessage(validateKey, valInfo, valObjValue, valInfo.name || dataObjInfo.getColumnName(colIndex), options, dataObjInfo);
    }
    if (extMsg !== null) {
        fail(extMsg);
    }

    return { validateResult, messageArr, firstObj };
};

/**
 * @method
 * @name resolveFocusObj
 * @description 검증 실패 시 포커스 이동 대상을 결정한다 (명세 §1).
 *  필드 규칙에 focus("컴포넌트ID") 지정 시 해당 컴포넌트, 미지정·미존재 시 검증 컴포넌트 자신.
 *  (분리 입력 등 실제 입력란이 따로 있는 경우 사용자 입력 위치로 유도)
 * @param {Object} valInfo 규칙 객체 (focus 옵션 포함 가능)
 * @param {Object} valObj 검증 대상 컴포넌트
 * @returns {Object} 포커스 이동 대상 컴포넌트
 * @hidden N
 * @exception
 * @example
 * const focusObj = scwin.resolveFocusObj({ focus : "ipt_corpRegNo1" }, valObj);
 */
scwin.resolveFocusObj = function (valInfo, valObj) {
    if (valInfo && !$c.util.isEmpty(valInfo.focus)) {
        const focusObj = $c.util.getComponent(valInfo.focus);
        if (!$c.util.isEmpty(focusObj)) { return focusObj; }
    }
    return valObj;
};

/**
 * @method
 * @name getRequiredMessage
 * @description required 실패 기본 메시지를 컴포넌트 유형에 따라 분기한다 (명세 §3).
 *  선택형(radio/checkbox/selectbox/checkcombobox/autoComplete/searchbox, 그리드 select·checkbox·radio 컬럼)
 *  → "선택하세요.", 그 외 입력형 → "입력하세요.". 필드 규칙 message 지정 시 그 문구로 재정의(명세 §5).
 *  ($c 공통함수 사용 함수 — 빌드 $p 주입 규칙에 따라 공개 선언·$c.validate 로 호출)
 * @param {String} name 조사 부착 항목 표시명
 * @param {Object} valInfo 규칙 객체 (message 재정의 참조)
 * @param {Object} valObj 검증 대상 컴포넌트 (그리드면 gridView)
 * @param {Number} colIndex (그리드) 컬럼 index — 컬럼 inputType 판정용
 * @returns {String} required 실패 메시지
 * @hidden N
 * @exception
 * @example
 * $c.validate.getRequiredMessage("결산월은(는)", {}, sbxMonth); // "결산월은(는) 선택하세요."
 */
scwin.getRequiredMessage = function (name, valInfo, valObj, colIndex) {
    if (valInfo && !$c.util.isEmpty(valInfo.message)) { return valInfo.message; }
    const SELECT_TYPES = ["RADIO", "CHECKBOX", "SELECTBOX", "CHECKCOMBOBOX", "AUTOCOMPLETE", "SEARCHBOX", "SELECT", "DROPDOWN"];
    let type = "";
    if (valObj && typeof valObj.getPluginName === "function") {
        type = valObj.getPluginName().toUpperCase();
        if (type === "GRIDVIEW") {
            type = (typeof valObj.getColumnInputType === "function" && colIndex !== undefined)
                ? String(valObj.getColumnInputType(colIndex) || "").toUpperCase() : "";
        }
    }
    const verb = SELECT_TYPES.includes(type) ? "선택" : "입력";
    return `${name} ${verb}하세요.`;
};

/**
 * @method
 * @name __getAllowCharMessage
 * @description allowChar 허용 패턴을 인식해 조합별 세부 안내 문구를 반환한다 (명세 §7).
 *  한글/영문/숫자/영문+숫자/영문+숫자+특수문자 조합을 인식하며, 인식 불가 조합은 null 반환
 *  (호출부에서 기존 범용 문구로 폴백).
 * @param {String} name 조사 부착 항목 표시명
 * @param {String} val allowChar 패턴 값 (예: "a-zA-Z0-9")
 * @returns {String} 세부 안내 문구 (인식 불가 시 null)
 * @hidden Y
 * @exception
 * @example
 * scwin.__getAllowCharMessage("코드는(는)", "a-zA-Z0-9"); // "코드는(는) 영문+숫자만 입력이 가능합니다."
 */
scwin.__getAllowCharMessage = function (name, val) {
    let rest = String(val);
    const strip = function (tokens) {
        let found = false;
        tokens.forEach(function (t) {
            if (rest.indexOf(t) !== -1) { found = true; rest = rest.split(t).join(""); }
        });
        return found;
    };
    const hasKor = strip(["가-힣", "ㄱ-ㅎ", "ㅏ-ㅣ"]);
    const hasEng = strip(["a-zA-Z", "A-Za-z", "a-z", "A-Z"]);
    const hasNum = strip(["0-9"]);
    const hasSpecial = rest.length > 0;   // 알려진 토큰 제거 후 남은 문자는 특수문자 허용 목록으로 간주

    if (hasKor && !hasEng && !hasNum && !hasSpecial) { return `${name} 한글만 입력이 가능합니다.`; }
    if (hasEng && !hasKor && !hasNum && !hasSpecial) { return `${name} 영문만 입력이 가능합니다.`; }
    if (hasNum && !hasKor && !hasEng && !hasSpecial) { return `${name} 숫자만 입력이 가능합니다.`; }
    if (hasEng && hasNum && !hasKor && !hasSpecial) { return `${name} 영문+숫자만 입력이 가능합니다.`; }
    if (hasEng && hasNum && hasSpecial && !hasKor) { return `${name} 영문+숫자+특수문자만 입력이 가능합니다.`; }
    return null;
};

/**
 * @method
 * @name __getByteLengthUtf8
 * @description UTF-8 기준 byte 수를 반환한다 — 한글 3byte (명세 §2 요건 확정값).
 *  ※ $c.str.getByteLength(WebSquare util)는 한글을 2byte 로 계산하므로 byte 검증 규칙
 *    (minLengthB/maxLengthB)은 이 함수를 사용한다.
 * @param {String} str 대상 문자열
 * @returns {Number} UTF-8 byte 수
 * @hidden Y
 * @exception
 * @example
 * scwin.__getByteLengthUtf8("1231a한글"); // 11 (5 + 3×2)
 */
scwin.__getByteLengthUtf8 = function (str) {
    let bytes = 0;
    for (const ch of String(str)) {
        const cp = ch.codePointAt(0);
        bytes += (cp <= 0x7F) ? 1 : ((cp <= 0x7FF) ? 2 : ((cp <= 0xFFFF) ? 3 : 4));
    }
    return bytes;
};

/**
 * @method
 * @name getExtendedRuleMessage
 * @description 확장 검증 규칙을 평가해 실패 메시지를 반환한다 (validateDataGroup/validateDataCollection 공용).
 *  ($c 공통함수 사용 함수 — 빌드 $p 주입 규칙에 따라 공개 선언·$c.validate 로 호출)
 *  지원 규칙: ignoreChar(입력 불가 문자) / minLengthB·maxLengthB(byte 길이 — UTF-8 기준·한글 3byte,
 *  maxLengthB 는 객체형 { value, msgType:"korEng", message } 지원 — 명세 §2) / maxLengthF(정수.소수 자리수)
 *  / num(n:숫자, i:정수, f:실수) / fromNum·toNum(숫자 범위) / format:bizNum(사업자등록번호)
 *  / format:corpNum(법인등록번호) / format:urlNoProtocol(프로토콜 제외 URL)
 *  / composition(문자 클래스 조합 필수 — eng/num/kor/special/upper/lower 각 1자 이상,
 *    프리셋 "engNum"·"engNumSpecial"·토큰 배열·객체형 { value, message } 지원).
 *  빈 값은 항상 통과시킨다(필수 여부는 required 규칙 소관).
 * @param {String} validateKey validate key 값 (대문자)
 * @param {String} val 규칙 값 (문자열화 — 객체형 규칙은 valInfo 에서 원본 참조)
 * @param {String} value 검증 대상 값
 * @param {String} fieldName 항목 표시명
 * @param {Object} valInfo 규칙 객체 원본 (maxLengthB 객체형 참조용, 생략 가능)
 * @returns {String} 실패 메시지 (통과 시 null)
 * @hidden N
 * @exception
 * @example
 * const extMsg = $c.validate.getExtendedRuleMessage("NUM", "i", "12.5", "나이"); // "나이는 정수 형식으로 입력해주세요."
 */
scwin.getExtendedRuleMessage = function (validateKey, val, value, fieldName, valInfo) {
    const s = (value === undefined || value === null) ? "" : String(value);
    if (s === "") {
        return null;
    }
    const name = $c.str.attachPostposition(fieldName);

    if (validateKey === "IGNORECHAR") {
        if (new RegExp("[" + val + "]").test(s)) {
            return `${name} 입력할 수 없는 문자(${val})가 포함되어 있습니다.`;
        }
    }

    if (validateKey === "MINLENGTHB") {
        if (scwin.__getByteLengthUtf8(s) < Number.parseInt(val, 10)) {
            return `${name} 최소 ${val}byte 이상 입력해주세요.`;
        }
    }

    if (validateKey === "MAXLENGTHB") {
        // 객체형 { value, msgType:"korEng", message } 지원 — byte 한도는 동일, 안내 문구만 분기 (명세 §2)
        const rule = (valInfo && valInfo.maxLengthB !== null && typeof valInfo.maxLengthB === "object") ? valInfo.maxLengthB : null;
        const limit = Number.parseInt(rule ? rule.value : val, 10);
        if (scwin.__getByteLengthUtf8(s) > limit) {
            if (rule && String(rule.msgType || "").toUpperCase() === "KORENG") {
                const korMax = Math.floor(limit / 3);   // 한글 3byte(UTF-8) 기준 환산 — 요건 확정값
                return rule.message || `${name} 한글 ${korMax}자 영문 ${limit}자 이내로 입력해주세요.`;
            }
            return `${name} 최대 ${limit}byte 이하로 입력해주세요.`;
        }
    }

    if (validateKey === "MAXLENGTHF") {
        const lim = String(val).split(".");
        const intMax = Number.parseInt(lim[0], 10);
        const decMax = Number.parseInt(lim[1] || "0", 10);
        const digits = s.replace(/,/g, "").replace(/^-/, "").split(".");
        if ((digits[0] || "").length > intMax || (digits[1] || "").length > decMax) {
            return `${name} 정수 ${intMax}자리, 소수점 ${decMax}자리 이내로 입력해주세요.`;
        }
    }

    if (validateKey === "NUM") {
        const type = String(val).toLowerCase();
        if (type === "n" && !/^\d+$/.test(s)) {
            return `${name} 숫자(0-9)만 입력해주세요.`;
        }
        if (type === "i" && !/^-?\d+$/.test(s)) {
            return `${name} 정수 형식으로 입력해주세요.`;
        }
        if (type === "f" && !/^-?\d+(\.\d+)?$/.test(s)) {
            return `${name} 숫자(실수) 형식으로 입력해주세요.`;
        }
    }

    if (validateKey === "FROMNUM") {
        const num = Number(s.replaceAll(",", ""));
        if (!Number.isNaN(num) && num < Number(val)) {
            return `${name} ${val} 이상으로 입력해주세요.`;
        }
    }

    if (validateKey === "TONUM") {
        const num = Number(s.replaceAll(",", ""));
        if (!Number.isNaN(num) && num > Number(val)) {
            return `${name} ${val} 이하로 입력해주세요.`;
        }
    }

    if (validateKey === "FORMAT" && String(val).toUpperCase() === "BIZNUM") {
        if (!$c.str.isBizID(s)) {
            return `${name} 정확한 사업자등록번호 형식을 입력해주세요.`;
        }
    }

    if (validateKey === "FORMAT" && String(val).toUpperCase() === "CORPNUM") {
        if (!$c.str.isCorpNum(s)) {
            return `${name} 정확한 법인등록번호 형식을 입력해주세요.`;
        }
    }

    if (validateKey === "FORMAT" && String(val).toUpperCase() === "URLNOPROTOCOL") {
        if (/^[A-Za-z][A-Za-z0-9+.-]*:\/\//.test(s)) {
            return `${name} 프로토콜(http:// 등)을 제외하고 입력해주세요.`;
        }
    }

    if (validateKey === "COMPOSITION") {
        // 문자 클래스 조합 필수 — 지정한 각 클래스의 문자가 1자 이상 포함돼야 통과 (아이디/비밀번호류).
        // allowChar(허용 외 문자 금지)와 상호보완 — 포함 강제가 필요하면 composition, 문자 제한은 allowChar.
        // 표기: 프리셋 문자열("engNum"|"engNumSpecial") | 토큰 배열(["eng","num",...]) | 객체형 { value, message }
        const rule = (valInfo && valInfo.composition !== null && typeof valInfo.composition === "object"
            && !Array.isArray(valInfo.composition)) ? valInfo.composition : null;
        const spec = rule ? rule.value : (valInfo ? valInfo.composition : undefined);
        const PRESETS = { engNum : ["eng", "num"], engNumSpecial : ["eng", "num", "special"] };
        const CLASS_RE = {
            eng : /[A-Za-z]/, num : /[0-9]/, kor : /[가-힣ㄱ-ㅎㅏ-ㅣ]/,
            special : /[^A-Za-z0-9가-힣ㄱ-ㅎㅏ-ㅣ\s]/, upper : /[A-Z]/, lower : /[a-z]/
        };
        const CLASS_NM = { eng : "영문", num : "숫자", kor : "한글", special : "특수문자", upper : "영문 대문자", lower : "영문 소문자" };
        const tokens = Array.isArray(spec) ? spec : (PRESETS[String(spec)] || []);
        if (tokens.length) {
            const unmet = tokens.filter(function (t) { return CLASS_RE[t] && !CLASS_RE[t].test(s); });
            if (unmet.length) {
                const label = tokens.map(function (t) { return CLASS_NM[t] || t; }).join("+");
                return (rule && rule.message) || `${name} ${label} 조합으로 입력해주세요.`;
            }
        }
    }

    return null;
};

/**
 * @method
 * @name getConditionalRuleMessage
 * @description 타 필드 참조가 필요한 조건부·그룹 규칙을 평가해 실패 메시지를 반환한다
 *  (validateDataGroup/validateDataCollection 공용).
 *  ($c 공통함수 사용 함수 — 빌드 $p 주입 규칙에 따라 공개 선언·$c.validate 로 호출)
 *  지원 규칙: checked(체크박스 필수 체크) / emptyIf(조건 충족 시 입력 금지) / requiredIf(조건 충족 시 필수)
 *  / duplicateGroup(폼 그룹 필드 간 중복 금지) / duplicate(그리드 컬럼 값 중복 금지)
 *  / compare(두 컴포넌트 값 비교 — 명세 §4) / matchValue(특정 값 일치 확인 — 명세 §5, 빈 값도 실패).
 *  emptyIf/requiredIf 조건 객체: { compID, equals | notEquals | in | notEmpty, message } — 참조 컴포넌트 값으로
 *  판정(equals > notEquals > in > notEmpty 순). notEquals 는 참조 값이 빈 경우 조건 불충족으로 처리한다
 *  (예: 국가코드가 대한민국("410")이 아니면 외국국적 — 미선택은 required 소관).
 *  compare 조건 객체: { compareTarget(비교 대상 컴포넌트 ID — compID 별칭 허용),
 *  compareType : "EQUAL"(일치해야 함) | "NOT_EQUAL"(달라야 함, 기본), message } — 두 값 모두 입력된 경우만 판정.
 *  matchValue 조건: { value | values(배열), message } 또는 값/배열 직접 지정 — 값 불일치(미입력 포함) 시 실패.
 * @param {String} validateKey validate key 값 (대문자)
 * @param {Object} valInfo 규칙 객체 (원본 rules + id/name)
 * @param {String} value 검증 대상 값
 * @param {String} fieldName 항목 표시명
 * @param {Object} options validateDataCollect options (duplicateGroup 이 fields 목록을 참조)
 * @param {Object} dataObjInfo DataCollection 정보 (그리드 duplicate 가 전체 행을 참조)
 * @returns {String} 실패 메시지 (통과 시 null)
 * @hidden N
 * @exception
 * @example
 * const condMsg = $c.validate.getConditionalRuleMessage("CHECKED", valInfo, "", "약관동의", options, dataObjInfo);
 */
scwin.getConditionalRuleMessage = function (validateKey, valInfo, value, fieldName, options, dataObjInfo) {
    const s = (value === undefined || value === null) ? "" : String(value);
    const name = $c.str.attachPostposition(fieldName);

    // 조건 객체 판정 — 참조 컴포넌트 값 기준
    function evalCondition(cond) {
        if ($c.util.isEmpty(cond) || typeof cond !== "object" || $c.util.isEmpty(cond.compID)) {
            return false;
        }
        const refComp = $c.util.getComponent(cond.compID);
        if ($c.util.isEmpty(refComp) || typeof refComp.getValue !== "function") {
            return false;
        }
        const refVal = String(refComp.getValue() === undefined || refComp.getValue() === null ? "" : refComp.getValue());
        if (cond.equals !== undefined) {
            return refVal === String(cond.equals);
        }
        if (cond.notEquals !== undefined) {
            // 참조 값이 빈 경우(미선택)는 판단 불가 — 조건 불충족 처리(미선택 자체는 required 로 검증)
            return refVal !== "" && refVal !== String(cond.notEquals);
        }
        if (Array.isArray(cond.in)) {
            return cond.in.map(String).includes(refVal);
        }
        if (cond.notEmpty === true) {
            return refVal !== "";
        }
        return false;
    }

    if (validateKey === "CHECKED" && String(valInfo.checked).toUpperCase() === "TRUE") {
        // 미체크 값(빈 값·falseValue 계열)은 전부 실패 처리 — required 와 달리 "0"/false 도 잡는다
        const FALSE_VALUES = ["", "0", "FALSE", "N", "OFF"];
        if (FALSE_VALUES.includes(s.toUpperCase())) {
            return `${name} 동의 해주세요.`;   // 문구 변경 — 명세 §6
        }
    }

    if (validateKey === "COMPARE") {
        // 두 컴포넌트 값 비교 (명세 §4) — 두 값 모두 입력된 경우만 판정(빈 값은 required 소관)
        const cmp = valInfo.compare;
        if (!$c.util.isEmpty(cmp) && typeof cmp === "object" && s !== "") {
            const targetId = cmp.compareTarget || cmp.compID;
            const targetComp = $c.util.isEmpty(targetId) ? null : $c.util.getComponent(targetId);
            if (!$c.util.isEmpty(targetComp) && typeof targetComp.getValue === "function") {
                const targetVal = targetComp.getValue();
                const t = String(targetVal === undefined || targetVal === null ? "" : targetVal);
                if (t !== "") {
                    const cmpType = String(cmp.compareType || "NOT_EQUAL").toUpperCase();
                    if (cmpType === "EQUAL" && s !== t) {
                        return cmp.message || `${name} 비교 대상과 값이 일치해야 합니다.`;
                    }
                    if (cmpType === "NOT_EQUAL" && s === t) {
                        return cmp.message || `${name} 동일한 값이 존재합니다.`;
                    }
                }
            }
        }
    }

    if (validateKey === "MATCHVALUE") {
        // 특정 값 일치 확인 (명세 §5) — 미입력도 실패(중복확인 여부 등 상태 플래그 점검용)
        const mv = valInfo.matchValue;
        if (!$c.util.isEmpty(mv) || mv === "" || mv === 0 || mv === false) {
            let expected;
            let mvMessage;
            if (mv !== null && typeof mv === "object" && !Array.isArray(mv)) {
                expected = (mv.values !== undefined) ? mv.values : mv.value;
                mvMessage = mv.message;
            } else {
                expected = mv;
            }
            const list = (Array.isArray(expected) ? expected : [expected]).map(String);
            if (!list.includes(s)) {
                return mvMessage || `${name} 값을 확인해주세요.`;
            }
        }
    }

    if (validateKey === "EMPTYIF") {
        const cond = valInfo.emptyIf;
        if (evalCondition(cond) && s !== "") {
            return cond.message || `${name} 현재 조건에서는 입력할 수 없습니다.`;
        }
    }

    if (validateKey === "REQUIREDIF") {
        const cond = valInfo.requiredIf;
        if (evalCondition(cond) && s === "") {
            return cond.message || `${name} 필수 입력사항입니다.`;
        }
    }

    if (validateKey === "DUPLICATEGROUP" && !$c.util.isEmpty(valInfo.duplicateGroup) && s !== "") {
        // 같은 duplicateGroup 명을 가진 fields 항목(compID 기준)들과 값 비교
        const groupName = valInfo.duplicateGroup;
        const fields = (options && options.fields) || {};
        const dupId = Object.keys(fields).find(function (fieldId) {
            if (fieldId === valInfo.id || fields[fieldId].duplicateGroup !== groupName) {
                return false;
            }
            const comp = $c.util.getComponent(fieldId);
            if ($c.util.isEmpty(comp) || typeof comp.getValue !== "function") {
                return false;
            }
            const compVal = comp.getValue();
            return String(compVal === undefined || compVal === null ? "" : compVal) === s;
        });
        if (dupId !== undefined) {
            return `${name} 다른 항목과 중복된 값입니다.`;
        }
    }

    if (validateKey === "DUPLICATE" && String(valInfo.duplicate).toUpperCase() === "TRUE" && s !== "") {
        // 그리드 연동 DataList 전체 행에서 같은 컬럼 값 중복 검사
        if (!$c.util.isEmpty(dataObjInfo) && typeof dataObjInfo.getAllJSON === "function") {
            const dupCount = dataObjInfo.getAllJSON().filter(function (rowData) {
                const cellVal = rowData[valInfo.id];
                return String(cellVal === undefined || cellVal === null ? "" : cellVal) === s;
            }).length;
            if (dupCount > 1) {
                return `${name} 중복된 값이 있습니다.`;
            }
        }
    }

    return null;
};

/**
 * @method
 * @name getGridViewDataList
 * @description GridView와 바인딩된 DataList 객체를 반환한다.
 *
 * @param {Object} gridViewObj 바인딩 된 DataList가 존재하는지 검증할 GridView 객체
 * @memberOf validate
 * @author WebSquare
 * @return {Object} 바인딩 된 DataList 객체 반환 (바인딩된 객체가 없을 경우 null 반환)
 * @hidden N
 * @exception
 * @example
// 바인딩 되어있는 경우
$c.validate.getGridViewDataList(grdFirst); // return 예시) DataList 객체

// 바인딩 되어있지 않은 경우
$c.validate.getGridViewDataList(grdFirst); // return 예시) null
 */
scwin.getGridViewDataList = async function (gridViewObj) {
    let dataListId = ($p.getComponentById(gridViewObj.getDataListInfo()?.id)) ? gridViewObj.getDataListInfo().id : gridViewObj.getDataList();

    if (dataListId !== "") {
        let dataList = $p.getComponentById(dataListId);
        if ((typeof dataList === "undefined") || (dataList === null)) {
            console.info("DataList(" + dataListId + ")를 찾을 수 없습니다.");
            return null;
        } else {
            return dataList;
        }
    } else {
        console.info(dataListId + "는 DataList가 세팅되어 있지 않습니다.");
        return null;
    }
};

/**
 * @method
 * @name getChildrenComponent
 * @description 특정 컴포넌트의 자식 컴포넌트를 배열로 반환한다.
 * @param {object} comObj 컴포넌트 객체
 * @param {object} options 하위 컴포넌트 검색 옵션 정보
 * options.excludeId 제외할 컴포넌트 id. 인자가 여러개일 경우 공백을 구분자로 사용
 * options.excludePlugin 제외할 컴포넌트 plugin 이름. 인자가 여러개일 경우 공백을 구분자로 사용.
 * options.includePlugin 포함 컴포넌트 플러그인 이름. 인자가 여러개일 경우 공백을 구분자로 사용함.
 * @returns {objects} 하위 컴포넌트 목록
 * @hidden N
 * @exception
 * @example
 */
scwin.getChildrenComponent = function (comObj, options) {
    if ($c.util.isEmpty(comObj)) return [];

    // UDC 컴포넌트는 제외
    let excludeId = comObj.childControlList?.reduce(function (a, b) {
        if (b.options === undefined) {
            a.push(b.id);
        }
        return a;
    }, []).join(' ');

    excludeId = ($c.util.isEmpty(options.excludeId)) ? "" : excludeId;
    options.excludeId = ($c.util.isEmpty(options.excludeId)) ? excludeId : `${options.excludeId} ${excludeId}`;

    return WebSquare.util.getChildren(comObj, options);
};

/**
 * @method
 * @name getDataCollection
 * @description 특정 컴포넌트에 바인된 DataList나 DataMap의 정보를 반환한다.
 * @param {object} comObj 컴포넌트 객체
 * @returns {object} dataCollection 정보
 * @hidden N
 * @exception
 * @example
 */
scwin.getDataCollection = function (comObj) {
    try {
        if ((typeof comObj !== "undefined") && (typeof comObj.getRef === "function")) {
            if (comObj.getPluginName() === "gridView") {
                return comObj.getDataListInfo();
            } else if (comObj.getPluginName() === "treeview") {
                return comObj.getDataListInfo().nodeset?.split(":")[1];
            } else {
                let ref = comObj.options.ref;
                if ((typeof ref !== "undefined") && (ref !== "")) {
                    let refArray = ref.substring(5).split(".");
                    if ((typeof refArray !== "undefined") && (refArray.length === 2)) {
                        let dataObjInfo = {};
                        if (refArray[0].startsWith(WebSquare.util.getMainFrame().$p.getFrameId())) {
                            dataObjInfo.runtimeDataCollectionId = refArray[0];
                        } else {
                            dataObjInfo.runtimeDataCollectionId = comObj.getScopeWindow().$p.getFrameId() + "_" + refArray[0];
                        }
                        dataObjInfo.dataColletionId = refArray[0];
                        dataObjInfo.columnId = refArray[1];
                        let dataType = $p.getComponentById(dataObjInfo.dataColletionId).initializeType || $p.getComponentById(dataObjInfo.dataColletionId).getPluginName();
                        if (dataType.toUpperCase() === "DATAMAP") {
                            dataObjInfo.columnName = $p.getComponentById(dataObjInfo.dataColletionId)?.getName(dataObjInfo.columnId);
                        } else {
                            dataObjInfo.columnName = $p.getComponentById(dataObjInfo.dataColletionId)?.getColumnName(dataObjInfo.columnId);
                        }
                        return dataObjInfo;
                    } else {
                        return null;
                    }
                } else {
                    return null;
                }
            }
        }
    } catch (e) {
        console.error("[$c.validate.getDataCollection] Exception :: " + e.message);
    }	
};

/**
 * @method
 * @name setFocus
 * @description component focus 공통함수
 * @param {object} objCom component 객체
 * @param {object} rowIndex row index
 * @param {object} colIndex col index
 * @param {Boolean} editMode - (기본값: true) gridView에서 편집 모드로 진입 여부
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setFocus = function (objCom, rowIndex, colIndex, editMode = true) {
	if (typeof objCom.getPluginName !== "undefined") {
        if (objCom.getPluginName() === "gridView") {
            objCom.setFocusedCell(rowIndex, colIndex, editMode);
        } else if (objCom.getPluginName() === "radio") {
            objCom.render.querySelector("input[type=radio]").focus();
        } else if (objCom.getPluginName() === "checkbox") {
            objCom.render.querySelector("input[type=checkbox]").focus();
        } else {
            objCom.focus();
        }
    } else {
        objCom.focus();
    }
};


/**
 * @method
 * @name isBirthDay
 * @description 6자리 생년월일 여부
 * @param {string} birthDay 6자리 생년월일
 * @returns {boolean} 6자리 생년월일 여부(true or false)
 * @hidden N
 * @exception
 * @example
 */
scwin.isBirthDay = function (birthDay) {
    let result = /^(?:[0-9]{2}(?:0[1-9]|1[0-2])(?:0[1-9]|[1,2][0-9]|3[0,1]))$/.test(birthDay);

    if (!result) return false;

    const year = parseInt(birthDay.slice(0, 2), 10);
    const month = parseInt(birthDay.slice(2, 4), 10);
    const day = parseInt(birthDay.slice(4, 6), 10);

    // 1900년 기준 체크
    const fullYear = 1900 + year;
    const date = new Date(fullYear, month - 1, day);

    return (date.getFullYear() === fullYear && date.getMonth() === month - 1 && date.getDate() === day);	
};

/**
 * @method
 * @name isValidDate
 * @description 문자열이 유효한 날짜 형식인지 확인합니다.
 * @param {string} dateStr 검사할 날짜 문자열
 * @param {string} format 검사할 날짜 형식 (선택사항, 기본값: 'YYYYMMDD')
 * @returns {boolean} 유효한 날짜 형식 여부 리턴(true or false)
 * @hidden N
 * @exception
 * @example
 */
scwin.isValidDate = function (dateStr, format = "YYYYMMDD") {
    // 빈 문자열 체크
    if (!dateStr) return false;

    // 형식에 따른 정규식 패턴 정의
    const patterns = {
        'YYYY-MM-DD': /^\d{4}-\d{2}-\d{2}$/,
        'MM/DD/YYYY': /^\d{2}\/\d{2}\/\d{4}$/,
        'DD.MM.YYYY': /^\d{2}\.\d{2}\.\d{4}$/,
        'YYYY/MM/DD': /^\d{4}\/\d{2}\/\d{2}$/,
        'YYYYMMDD': /^\d{8}$/
    };

    // 지정된 형식의 패턴 가져오기
    const pattern = patterns[format];
    if (!pattern) return false;

    // 패턴과 일치하는지 확인
    if (!pattern.test(dateStr)) return false;

    // 날짜 구성요소 추출
    let year, month, day;

    if (format === 'YYYY-MM-DD') {
        [year, month, day] = dateStr.split('-').map(Number);
    } else if (format === 'MM/DD/YYYY') {
        [month, day, year] = dateStr.split('/').map(Number);
    } else if (format === 'DD.MM.YYYY') {
        [day, month, year] = dateStr.split('.').map(Number);
    } else if (format === 'YYYY/MM/DD') {
        [year, month, day] = dateStr.split('/').map(Number);
    } else if (format === 'YYYYMMDD') {
        // YYYYMMDD 형식은 구분자가 없으므로 직접 추출
        year = parseInt(dateStr.substring(0, 4));
        month = parseInt(dateStr.substring(4, 6));
        day = parseInt(dateStr.substring(6, 8));
    }

    // 월과 일 범위 검사
    if (month < 1 || month > 12) return false;

    // 각 월의 일수 확인 (윤년 고려)
    const isLeapYear = (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
    const daysInMonth = [31, isLeapYear ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

    return day >= 1 && day <= daysInMonth[month - 1];
};

/**
 * @method
 * @name validateSiteUrl
 * @description 프로토콜은 http, https 만 허용, 도메인은 최소 한개이상의 . 필요 , 도메인은 영문/숫자/하이픈만 허용 , 공백 금지
 * @param {string} url site url
 * @param {object} options { requireProtocol : 프로토콜 필수 여부(기본 false), forbidProtocol : 프로토콜 입력 금지 여부(기본 false) }
 * @returns {object} 유효성체크 반환값 { valid: false, code: "EMPTY", message: "값이 비어있습니다." };
 * @hidden N
 * @exception
 * @example
 */
scwin.validateSiteUrl = function(url, options = {}) {
    let requireProtocol = options.requireProtocol === true;   // 기본 false

    // 0. 기본 타입/빈값 체크
    if (typeof url !== "string" || url.trim() === "") {
        return { valid: false, code: "EMPTY", message: "url 은 필수값입니다." };
    }

    // 1. 공백 포함 금지
    if (/\s/.test(url)) {
        return { valid: false, code: "HAS_SPACE", message: WebSquare.WebSquareLang['com_empty_0057']};
    }

    // 2. 프로토콜 검사
    var rest = url;
    var m = url.match(/^([A-Za-z][A-Za-z0-9+.-]*):\/\//);  // 임의의 프로토콜 감지
    if (m) {
        // 프로토콜 입력 금지 옵션 — 포함 자체를 실패 처리 (제거 후 재입력 유도)
        if (options.forbidProtocol === true) {
            return { valid: false, code: "PROTOCOL_FORBIDDEN",
                     message: "프로토콜(http:// 등)을 제외하고 입력해주세요." };
        }
        // 프로토콜이 있는 경우 → http/https 만 허용 (항상 검사)
        var proto = m[1].toLowerCase();
        if (proto !== "http" && proto !== "https") {
            return { valid: false, code: "BAD_PROTOCOL",
                     message: "프로토콜은 http, https 만 허용됩니다. (입력: " + m[1] + ")" };
        }
        rest = url.slice(m[0].length);
    } else {
        // 프로토콜이 없는 경우 → 옵션에 따라 허용 여부 결정
        if (requireProtocol) {
            return { valid: false, code: "PROTOCOL_REQUIRED",
                     message: "프로토콜(http:// 또는 https://)이 필요합니다." };
        }
        // requireProtocol=false 이면 통과
    }

    // 3. 도메인 부분만 추출 (경로/포트/쿼리 제거)
    var host = rest.split(/[\/?#:]/)[0];
    if (host === "") {
        return { valid: false, code: "NO_DOMAIN", message: "도메인이 없습니다." };
    }

    // 4. '.' 최소 한 개 이상 포함
    if (host.indexOf(".") === -1) {
        return { valid: false, code: "NO_DOT", message: "도메인에 '.'이 최소 한 개 이상 있어야 합니다." };
    }

    // 5. 라벨 규칙 검사 : 영문/숫자/하이픈만, 앞뒤 하이픈 금지, 빈 라벨 금지
    var labels = host.split(".");
    var labelRe = /^[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$/;
    for (var i = 0; i < labels.length; i++) {
        var lb = labels[i];
        if (lb === "") {
            return { valid: false, code: "EMPTY_LABEL",
                     message: "'.' 앞뒤로 빈 라벨이 있습니다. (예: 연속된 '..' 또는 시작/끝의 '.')" };
        }
        if (/[^A-Za-z0-9-]/.test(lb)) {
            return { valid: false, code: "INVALID_CHAR",
                     message: "라벨에 허용되지 않는 문자가 있습니다. 영문/숫자/하이픈만 가능. (문제 라벨: " + lb + ")" };
        }
        if (!labelRe.test(lb)) {
            return { valid: false, code: "HYPHEN_POSITION",
                     message: "라벨은 하이픈으로 시작하거나 끝날 수 없습니다. (문제 라벨: " + lb + ")" };
        }
    }

    return { valid: true, code: "OK", message: "유효한 주소입니다." };
}
